import {scenes,failures,sceneOrder} from './episode.js';
import {fresh,enter,advance,choose,retry,replay,lines,lineText,defaultSettings} from './engine.js';
import {load,save,erase} from './storage.js';
import * as audio from './audio.js';
const app=document.querySelector('#app'),overlay=document.querySelector('#overlay'),notice=document.querySelector('#notice');
let storage;try{storage=localStorage;}catch{storage={getItem(){throw Error()},setItem(){throw Error()},removeItem(){throw Error()}};}
const loaded=load(storage);let state=loaded.state||fresh(),hasSave=!!loaded.state,saveBlocked=!!loaded.error,view='title',revealTimer,revealed=true,lastInput=0,lastStage='',motionTimer,missingArt=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');
const reduced=()=>state.settings.reduced||motionQuery.matches;
function notify(text){notice.textContent=text;clearTimeout(notify.timer);notify.timer=setTimeout(()=>notice.textContent='',6500);}
function persist(){if(saveBlocked)return;if(!save(storage,state)){notify('Progress could not be saved. You can keep playing, but this session may be lost when you close the page.');}else hasSave=true;}
function apply(next){state=next;persist();render();}
function btn(label,action,cls=''){return `<button class="${cls}" data-action="${action}">${label}</button>`;}
const models={pip:{w:1983,h:793,ranges:[[15,336],[343,816],[863,1158],[1254,1559],[1617,1972]],poses:['neutral','heroic','worried','embarrassed','determined']},nell:{w:1774,h:887,ranges:[[79,387],[521,834],[914,1284],[1346,1716]],poses:['neutral','skeptical','repairing','warm']},brindle:{w:2172,h:724,ranges:[[69,495],[597,1031],[1087,1545],[1606,2154]],poses:['neutral','tea','explaining','supporting']},quill:{w:1774,h:887,ranges:[[151,689],[819,1084],[1234,1481]],poses:['announcing','defensive','anxious']}};
function character(id,pose='neutral',speaker=''){if(id==='pip'&&state.scene==='S00')return `<div class="actor pip uncloaked" role="img" aria-label="Pip holding his application, before borrowing the cloak" style="--ratio:${582/1536}"><div class="sprite" style="aspect-ratio:582/1536;background-image:url(assets/pip-uncloaked.png);background-size:${1024/582*100}% 100%;background-position:${246/(1024-582)*100}% 0"></div></div>`;const m=models[id];if(!m)return '';let index=m.poses.indexOf(pose);if(index<0)index=0;const [x,right]=m.ranges[index],width=right-x;return `<div class="actor ${id} ${speaker.toLowerCase()===id?'speaking':''}" role="img" aria-label="${id[0].toUpperCase()+id.slice(1)}, ${pose}" style="--ratio:${width/m.h}"><div class="sprite" style="aspect-ratio:${width}/${m.h};background-image:url(assets/${id}.png);background-size:${m.w/width*100}% 100%;background-position:${x/(m.w-width)*100}% 0"></div></div>`;}
function header(){return `<header class="topbar"><button data-action="title" class="wordmark" aria-label="Return to title">Fake It Till You Make It<span>A HERO FOR THE AFTERNOON</span></button><nav aria-label="Game menu">${btn('Scene map','map')}${btn(state.settings.muted?'Sound off':'Sound on','mute')}${btn('Settings','settings')}</nav></header>`;}
function background(scene){return scene.bg==='bridge'&&scene.dusk?'bridge-open':scene.bg;}
function stage(scene,line){const failure=state.phase==='failure'?failures[state.route.failure]:null;const key=state.scene+':'+(failure?.cue||'normal');const entering=lastStage!==key;lastStage=key;const cast=scene.cast||[];const speaker=line?.speaker||'';
let content=cast.map(id=>character(id,speaker.toLowerCase()===id?line.pose:'neutral',speaker)).join('');
if(failure){const [x,y,w,h]=[[25,15,355,480],[382,65,374,430],[756,65,380,451],[1135,132,392,381],[10,518,390,464],[425,494,300,488],[729,536,374,444],[1109,520,418,464]][failure.cell];content=`<div class="gag-frame" style="aspect-ratio:${w}/${h}"><div class="gag ${failure.cue}" role="img" aria-label="${esc(failure.action)}" style="background-size:${1536/w*100}% ${1024/h*100}%;background-position:${x/(1536-w)*100}% ${y/(1024-h)*100}%"></div></div><div class="gag-label">${failure.cue==='bunting'?'CONGRATULATIONS':failure.cue==='papers'?'PROCESSED':failure.cue==='dragon'?'One possible version of events…':''}</div>`;}
return `<section class="stage ${scene.dusk?'dusk':''} ${entering?'entering':''} ${failure?'failure-stage':''} ${state.scene==='S05'&&state.phase==='response'?'repair-'+state.facts.repairStyle:''}" aria-label="${esc(scene.location)}"><img class="backdrop" src="assets/${background(scene)}.png" alt="${esc(scene.location)}" onerror="this.dataset.failed='true'"><div class="vignette"></div><div class="scene-heading"><span>${esc(scene.location)}</span><h1>${esc(scene.title)}</h1></div><div class="cast cast-${cast.length}">${content}</div>${speaker==='Alder'?'<figure class="alder-memory" role="img" aria-label="A remembered portrait of Captain Alder"><div></div><figcaption>Captain Alder</figcaption></figure>':''}${state.scene==='S07'&&!failure?'<aside class="gate-clue"><strong>☀︎ Sunrise · ☼ Midday · ☾ Moon</strong><span>Wake the keeper; greet the day.<br>Noon and night must wait their say.</span></aside>':''}${state.scene==='S03'&&!failure?'<div class="bridge-sign">UNSAFE<br><small>Please read the second word too.</small></div>':''}<div class="observations" aria-label="Optional observations">${(scene.observations||[]).map((o,i)=>`<button data-observe="${i}"><span aria-hidden="true">＋</span> ${esc(o[0])}</button>`).join('')}</div></section>`;}
function render(){clearInterval(revealTimer);clearTimeout(motionTimer);document.body.classList.toggle('reduced-motion',reduced());audio.configure(state.settings,['S07','S08'].includes(state.scene)?'mystery':'town');
if(view==='title'){lastStage='';app.innerHTML=`<div class="title-screen"><img class="title-art" src="assets/town.png" alt="The empty hero’s chair waits in Bellwether’s lantern-strung square"><div class="title-shade"></div><section class="title-content"><p class="eyebrow">A SMALL HERO. A VERY LARGE CLOAK.</p><h1>Fake It<br><em>Till You</em><br>Make It</h1><p class="episode">EPISODE ONE<span>A Hero for the Afternoon</span></p><div class="title-actions">${hasSave?btn('Continue the adventure','continue','primary'):''}${btn('New game','new',hasSave?'':'primary')}${state.discoveries.endingsSeen.length?btn('Scene map','map'):''}${btn('Settings','settings')}${btn('Credits','credits')}</div><p class="title-foot">A storybook adventure · About 15–20 minutes<br>Progress saves in this browser.</p></section><div class="title-caption">Bellwether needs a hero.<br>It has you.</div></div>`;if(loaded.error&&!render.recoveryShown){render.recoveryShown=true;queueMicrotask(()=>showRecovery());}bind();return;}
const scene=scenes[state.scene];const line=['dialogue','response'].includes(state.phase)?lines(state)[state.beat]:null;
let panel='';if(line){const text=lineText(line,state.facts);panel=`<section class="dialogue" aria-label="Story dialogue"><div class="dialogue-text"><span class="speaker ${line.speaker.toLowerCase()}">${esc(line.speaker==='Narrator'?'':line.speaker==='Alder'?'Alder · remembered words':line.speaker)}</span><p class="${line.speaker==='Narrator'?'narration':''}"><span id="visible-line" aria-hidden="true"></span><span class="sr-only">${esc(text)}</span></p></div><div class="dialogue-controls"><span class="input-hint">Click, Enter, or Space</span>${btn('Continue','advance','primary')}</div></section>`;}
if(state.phase==='choice'){panel=`<section class="choice-panel"><div class="choice-heading"><p>What will Pip do?</p><span>Take your time. Curiosity is encouraged.</span></div><div class="choices">${scene.choices.map((c,i)=>`<button data-choice="${c.id}"><span class="choice-number">${String(i+1).padStart(2,'0')}</span><span>${esc(c.label)}</span></button>`).join('')}</div></section>`;}
if(state.phase==='failure'){const f=failures[state.route.failure];panel=`<section class="failure-panel"><div><span class="eyebrow">A PERFECTLY AVOIDABLE INCIDENT</span><h2>${esc(f.title)}</h2><p>${esc(f.action)}</p><p class="reaction">${esc(f.reaction)}</p></div><div class="failure-actions">${btn('Try that again','retry','primary')}${btn('Scene map','map')}</div></section>`;}
if(state.phase==='ending'){panel=`<section class="ending-panel"><div><p class="eyebrow">EPISODE ONE COMPLETE</p><h2>${esc(scene.card)}</h2><p>The crossing is safe. You earned your badge.<br>Alder’s trail leads beneath the old bellhouse.</p></div><div>${btn('Explore the scene map','map','primary')}${btn('Credits','credits')}${btn('Back to title','title')}</div></section>`;}
app.innerHTML=`<div class="game-shell">${header()}${stage(scene,line)}${panel}<footer class="game-footer"><span>EPISODE 01 <span aria-hidden="true">/</span> ${state.scene.startsWith('E')?'EPILOGUE':String(Number(state.scene.slice(1))+1).padStart(2,'0')+' OF 11'}</span><span>${state.facts.alderNote?'Alder’s note kept safe':state.facts.bellSeal?'The bell seal found':state.facts.alderVisited?'Alder’s trail found':'A hero for the afternoon'}</span></footer></div>`;
bind();if(line)startReveal(lineText(line,state.facts));if(state.phase==='choice')app.querySelector('[data-choice]')?.focus({preventScroll:true});if(state.phase==='failure')audio.effect('failure');if(state.phase==='ending')audio.effect('success');
if(!missingArt)app.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{missingArt=true;notify('An illustration could not load. Please check your connection and reload; your saved progress is kept.');},{once:true}));}
function startReveal(text){const span=document.querySelector('#visible-line');revealed=state.settings.instant||reduced();span.textContent=revealed?text:'';if(revealed)return;let n=0;revealTimer=setInterval(()=>{n+=2;span.textContent=text.slice(0,n);if(n>=text.length){revealed=true;clearInterval(revealTimer);}},20);}
function next(){if(view!=='game'||overlay.open||!['dialogue','response'].includes(state.phase))return;if(!revealed){revealed=true;clearInterval(revealTimer);document.querySelector('#visible-line').textContent=lineText(lines(state)[state.beat],state.facts);return;}apply(advance(state));}
function begin(){audio.unlock(state.settings);view='game';apply(fresh(state.discoveries,state.settings));}
function newGame(){if(hasSave||saveBlocked){confirm('Start a new adventure?','This replaces your current run. Discovered scenes, incidents, and endings stay in your collection.',()=>{saveBlocked=false;begin();});}else begin();}
function bind(){app.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));app.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>{if(state.phase!=='choice')return;audio.unlock(state.settings);apply(choose(state,b.dataset.choice));}));app.querySelectorAll('[data-observe]').forEach(b=>b.addEventListener('click',()=>{const [title,text]=scenes[state.scene].observations[+b.dataset.observe];modal(`<p class="eyebrow">A CLOSER LOOK</p><h2>${esc(title)}</h2><p>${esc(text)}</p>${btn('Back to the story','close','primary')}`);}));app.querySelector('.dialogue-text')?.addEventListener('click',next);}
function action(id){if(id==='advance')next();if(id==='new')newGame();if(id==='continue'){view='game';audio.unlock(state.settings);render();}if(id==='retry'){audio.unlock(state.settings);apply(retry(state));}if(id==='title'){view='title';render();}if(id==='map')showMap();if(id==='settings')settings();if(id==='credits')credits();if(id==='mute'){state.settings.muted=!state.settings.muted;audio.unlock(state.settings);persist();render();}if(id==='close')overlay.close();}
function modal(html){overlay.innerHTML=`<button class="close" aria-label="Close dialog" data-action="close">×</button>${html}`;overlay.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));if(!overlay.open)overlay.showModal();overlay.querySelector('h2')?.setAttribute('id','modal-title');overlay.setAttribute('aria-labelledby','modal-title');}
function confirm(title,text,done){modal(`<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="modal-actions">${btn('Keep playing','close')}<button id="confirm-action" class="primary">Confirm</button></div>`);overlay.querySelector('#confirm-action').onclick=()=>{overlay.close();done();};}
function settings(){modal(`<p class="eyebrow">MAKE YOURSELF COMFORTABLE</p><h2>Settings</h2><label class="toggle"><span>Sound on</span><input id="sound" type="checkbox" ${!state.settings.muted?'checked':''}></label><label class="range">Music <output id="music-value">${Math.round(state.settings.music*100)}%</output><input id="music" type="range" min="0" max="100" value="${state.settings.music*100}"></label><label class="range">Effects <output id="effects-value">${Math.round(state.settings.effects*100)}%</output><input id="effects" type="range" min="0" max="100" value="${state.settings.effects*100}"></label><label class="toggle"><span>Instant text</span><input id="instant" type="checkbox" ${state.settings.instant?'checked':''}></label><label class="toggle"><span>Reduce motion${motionQuery.matches?' (system preference active)':''}</span><input id="reduced" type="checkbox" ${state.settings.reduced?'checked':''}></label><div class="save-note"><strong>Your progress stays in this browser.</strong><p>No account or cloud save. Clearing site data, changing browsers, or using a private window can remove progress.</p></div><div class="modal-actions"><button id="restart">Restart episode</button><button id="erase" class="danger">Erase all progress</button></div><p class="fine">Enter or Space advances dialogue. During text reveal, the first press reveals the line. Use Tab and Enter to choose. Escape closes menus.</p>`);
['sound','instant','reduced','music','effects'].forEach(id=>overlay.querySelector('#'+id).addEventListener('input',e=>{if(id==='sound')state.settings.muted=!e.target.checked;else if(['instant','reduced'].includes(id))state.settings[id]=e.target.checked;else{state.settings[id]=+e.target.value/100;overlay.querySelector('#'+id+'-value').textContent=e.target.value+'%';}audio.unlock(state.settings);persist();document.body.classList.toggle('reduced-motion',reduced());}));overlay.querySelector('#restart').onclick=newGame;overlay.querySelector('#erase').onclick=()=>confirm('Erase everything?','This removes this browser’s saved run, discovered incidents, endings, and settings. This cannot be undone.',()=>{if(!erase(storage)){notify('This browser did not allow saved progress to be erased.');return;}state=fresh();hasSave=false;saveBlocked=false;view='title';render();});}
function showMap(){const d=state.discoveries;modal(`<p class="eyebrow">PIP’S FIELD NOTES</p><h2>The afternoon, so far</h2><p>Replay a visited scene from the state you had when you arrived. Your discoveries stay with you.</p><div class="scene-map">${sceneOrder.filter(id=>!id.startsWith('E')).map((id,i)=>state.checkpoints[id]?`<button data-replay="${id}"><span>${String(i+1).padStart(2,'0')}</span>${esc(scenes[id].title)}</button>`:`<div class="unknown"><span>${String(i+1).padStart(2,'0')}</span>Undiscovered</div>`).join('')}</div><h3>Perfectly avoidable incidents <span>${d.failuresSeen.length}/8</span></h3><div class="collection">${Object.entries(failures).map(([id,f])=>`<div class="${d.failuresSeen.includes(id)?'found':'unknown'}">${d.failuresSeen.includes(id)?esc(f.title):'◆ Unexplored possibility'}</div>`).join('')}</div><h3>Ways the afternoon can end <span>${d.endingsSeen.length}/3</span></h3><div class="collection">${sceneOrder.filter(id=>id.startsWith('E')).map(id=>d.endingsSeen.includes(id)?`<button data-replay="${id}">${esc(scenes[id].title)}</button>`:'<div class="unknown">◆ A story yet to finish</div>').join('')}</div>`);overlay.querySelectorAll('[data-replay]').forEach(b=>b.onclick=()=>{const id=b.dataset.replay;confirm('Return to this scene?',`Your current run will continue from “${scenes[id].title}” with that scene’s saved facts.`,()=>{view='game';apply(replay(state,id));});});}
function credits(){modal(`<p class="eyebrow">THE PEOPLE OF BELLWETHER THANK YOU</p><h2>Fake It Till You Make It</h2><p><em>Episode one: A Hero for the Afternoon</em></p><p>Created for Eric Zhu. Story, design, engineering, and original procedural score developed with Codex. Original cartoon artwork generated with OpenAI’s included image-generation tool, from a shared character reference.</p><p>No commercial music, stock character packs, or live AI calls are used during play. The complete asset provenance and prompts are included in the source repository.</p><p>Inspired by the joy of memorable adventure characters and playful branching stories. All characters and dialogue here are original.</p><p class="fine">The public repository does not grant an overall open-source license. See ASSET-LICENSES.md for asset provenance. Episode two is a possibility, not an available chapter.</p>${btn('Back to the story','close','primary')}`);}
function showRecovery(){modal(`<h2>Your save needs attention</h2><p>${esc(loaded.error)}</p><p>You can keep the original data untouched or confirm a new adventure. A new run will replace the unreadable save.</p>${btn('Keep the original save','close')}<button id="recover" class="primary">Start a new adventure</button>`);overlay.querySelector('#recover').onclick=()=>newGame();}
overlay.addEventListener('close',()=>{if(view==='game')render();});
document.addEventListener('keydown',e=>{if(e.repeat||!['Enter',' '].includes(e.key)||overlay.open||/INPUT|BUTTON|SELECT|TEXTAREA|A/.test(e.target.tagName))return;if(performance.now()-lastInput<120)return;lastInput=performance.now();e.preventDefault();next();});
motionQuery.addEventListener('change',()=>render());
// Structured access reads only what the current player can already see.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_current_story',title:'Read the current story beat',description:'Read the visible story beat and available choices without advancing or revealing future scenes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('Expected an empty object');const scene=scenes[state.scene];return {screen:view,scene:view==='game'?scene.title:null,phase:view==='game'?state.phase:null,text:view==='game'&&['dialogue','response'].includes(state.phase)?lineText(lines(state)[state.beat],state.facts):null,choices:view==='game'&&state.phase==='choice'?scene.choices.map(c=>({id:c.id,label:c.label})):[]};}})).catch(()=>{});}catch{}}
render();
